 lessons[id]=dict(title=title,word=word,visual=visual,story=story,parts=[dict(form=a,meaning=b,origin=c) for a,b,c in parts],family=family,rule=rule,levels={k:dict(model=models[i],note=notes[i]) for i,k in enumerate(['A2','B1','B2'])},check=dict(question=question,choices=choices,answer=answer,reason=reason),transfer=dict(context=context,choices=cchoices,answer=canswer,reason=creason),prompt=prompt,sources=sources)
